def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    colors = {v for row in grid for v in row if v != bg}
    fg = next(iter(colors))
    out = [row[:] for row in grid]
    for r in range(h):
        cols = [c for c, v in enumerate(grid[r]) if v == fg]
        if len(cols) > 1:
            for c in range(min(cols), max(cols) + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == fg]
        if len(rows) > 1:
            for r in range(min(rows), max(rows) + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out
